import re

def expand_vars(template, variables):
    def swap(m):
        name = m.group(1) or m.group(2)
        return str(variables.get(name, ""))
    return re.sub(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}|\$([A-Za-z_][A-Za-z0-9_]*)", swap, template)

