nginx-smooth-wrr.solution:
def smooth_wrr(weights, n):
    if not weights:
        return []
    total = sum(weights)
    current = [0] * len(weights)
    out = []
    for _ in range(n):
        best = 0
        for i, w in enumerate(weights):
            current[i] += w
            if current[i] > current[best]:
                best = i
        current[best] -= total
        out.append(best)
    return out

