def least_conn(weights, events):
    active = [0] * len(weights)
    placed = {}
    out = []
    for kind, rid in events:
        if kind == "req":
            best = 0
            for i in range(1, len(weights)):
                if active[i] * weights[best] < active[best] * weights[i]:
                    best = i
            active[best] += 1
            placed[rid] = best
            out.append(best)
        else:
            server = placed.pop(rid, None)
            if server is not None:
                active[server] -= 1
    return out

