def split_clients(buckets, hash_value):
    total = 0
    for percent, value in buckets:
        if percent == "*":
            return value
        total += round(float(percent.rstrip("%")) * 100)
        if hash_value < total * 4294967295 // 10000:
            return value
    return ""

