nginx-limit-conn.solution:
def limit_conn(limit, events):
    counts = {}
    owner = {}
    out = []
    for event in events:
        if event[0] == "open":
            conn_id, key = event[1], event[2]
            if key == "":
                out.append("pass")
            elif counts.get(key, 0) >= limit:
                out.append("reject")
            else:
                counts[key] = counts.get(key, 0) + 1
                owner[conn_id] = key
                out.append("pass")
        else:
            key = owner.pop(event[1], None)
            if key is not None:
                counts[key] -= 1
    return out

