def https_redirect(scheme, host, uri, forwarded_proto, canonical, hsts_max_age):
    client_scheme = forwarded_proto or scheme
    name = host.lower().split(":")[0]
    hsts = "max-age=%d" % hsts_max_age if hsts_max_age > 0 else ""
    if client_scheme != "https":
        return [301, "https://" + canonical + uri, ""]
    if name != canonical:
        return [301, "https://" + canonical + uri, hsts]
    return [200, "", hsts]

nginx-log-parse.solution:
import re

_PATTERN = re.compile(r'^(\S+) - (\S+) \[([^\]]+)\] "([^"]*)" (\d{3}) (\d+) "([^"]*)" "([^"]*)"$')

def parse_log(line):
    m = _PATTERN.match(line.strip())
    if not m:
        return None
    addr, user, when, request, status, size, referer, agent = m.groups()
    parts = request.split(" ")
    if len(parts) == 3 and all(parts):
        method, uri, protocol = parts
    else:
        method, uri, protocol = "", request, ""
    return {"addr": addr, "user": user, "time": when, "method": method, "uri": uri, "protocol": protocol,
            "status": int(status), "bytes": int(size), "referer": referer, "agent": agent}

